const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
// Respect the PRD's medium interaction profile: small, damped cursor tilt only.
const visual=$('.hero-visual'); visual?.addEventListener('pointermove',e=>{const r=visual.getBoundingClientRect();const x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;$('.polyhedron').style.transform=`rotate(18deg) perspective(500px) rotateY(${x*10}deg) rotateX(${-y*10}deg)`}); visual?.addEventListener('pointerleave',()=>$('.polyhedron').style.transform='');
$$('.toggle button').forEach(btn=>btn.addEventListener('click',()=>{$$('.toggle button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');const dash=btn.dataset.preview==='dashboard';const frame=$('#ikbar-preview');frame.querySelector('.browser-bar span').textContent=dash?'ikbar-barbershop-5rx3.vercel.app/dashboard':'ikbar-barbershop.vercel.app';frame.querySelector('.browser-content').innerHTML=dash?'<div class="browser-brand">IKBAR<span>.</span> / CMS</div><div class="browser-title">Shape your<br><em>storefront.</em></div><div class="browser-rule"></div><div class="browser-chips"><span>Services</span><span>Content</span><span>Theme</span></div><div class="browser-cta">Save & publish ↗</div>':'<div class="browser-brand">IKBAR<span>.</span></div><div class="browser-title">Your cut,<br><em>elevated.</em></div><div class="browser-rule"></div><div class="browser-chips"><span>Classic cut</span><span>Skin fade</span><span>Beard trim</span></div><div class="browser-cta">Book an appointment ↗</div>'}));
const grid=$('#path-grid'), cols=16, rows=8, start=2, end=125; for(let i=0;i<cols*rows;i++){const c=document.createElement('button');c.className='cell';c.setAttribute('aria-label',`Grid cell ${i+1}`);if(i===start)c.classList.add('start');if(i===end)c.classList.add('end');c.addEventListener('click',()=>{if(i!==start&&i!==end)c.classList.toggle('wall')});grid.append(c)}
$('#clear-path').addEventListener('click',()=>$$('.cell').forEach((c,i)=>{c.className='cell';if(i===start)c.classList.add('start');if(i===end)c.classList.add('end')}));
$('#run-path').addEventListener('click',()=>{const cells=$$('.cell');cells.forEach(c=>c.classList.remove('visited','path'));let i=0;const timer=setInterval(()=>{if(i>=cells.length){clearInterval(timer);cells.filter(c=>c.classList.contains('visited')).slice(-9).forEach(c=>c.classList.add('path'));$('#runtime').textContent='COMPLETE / 2.4 ms';return}if(!cells[i].classList.contains('wall')&&!cells[i].classList.contains('start')&&!cells[i].classList.contains('end'))cells[i].classList.add('visited');i++;},12);$('#runtime').textContent='RUNNING / … ms'});
$$('.lab-tab').forEach(btn=>btn.addEventListener('click',()=>{$$('.lab-tab').forEach(b=>b.classList.remove('active'));btn.classList.add('active');$$('.lab-panel').forEach(p=>p.classList.add('hidden'));$(`#${btn.dataset.lab}-lab`).classList.remove('hidden')}));
const radius=$('#radius-range'), preview=$('#token-preview');radius.addEventListener('input',e=>{preview.style.borderRadius=e.target.value+'px';$('#radius-output').textContent=e.target.value+'px'});$('#accent-select').addEventListener('change',e=>{const values={sky:['Sky blue','var(--sky)'],snow:['Snow blue','var(--ice)'],gold:['Champagne gold','var(--gold)']};const [label,color]=values[e.target.value];$('#accent-output').textContent=label;preview.style.borderColor=color;preview.querySelector('h4 em').style.color=color});
const toast=$('#toast');function showToast(msg){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)}$('.copy-email')?.addEventListener('click',()=>showToast('Add your email address in Studio first'));
$$('.menu-toggle').forEach(btn=>btn.addEventListener('click',()=>{$('.nav-links').style.display=$('.nav-links').style.display==='flex'?'none':'flex';$('.nav-links').style.position='absolute';$('.nav-links').style.top='60px';$('.nav-links').style.left='20px';$('.nav-links').style.right='20px';$('.nav-links').style.padding='18px';$('.nav-links').style.background='white';$('.nav-links').style.borderRadius='14px';$('.nav-links').style.flexDirection='column'}));
